// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {NairaSwapPair} from "./NairaSwapPair.sol";

/// @notice Permissionless CREATE2 pair factory with delayed fee-recipient changes.
contract NairaSwapFactory is Ownable2Step {
    /// @notice Minimum fee-recipient change delay.
    uint256 public constant FEE_DELAY = 2 days;
    /// @notice Recipient of protocol-fee LP tokens.
    address public feeTo;
    /// @notice Queued recipient, or zero if nothing is queued.
    address public pendingFeeTo;
    /// @notice Earliest application timestamp, or zero if nothing is queued.
    uint256 public pendingFeeToAt;
    /// @notice Pair registry, populated in both token directions.
    mapping(address => mapping(address => address)) public getPair;
    /// @notice All deployed pairs in creation order.
    address[] public allPairs;

    error IdenticalAddresses();
    error ZeroAddress();
    error PairExists();
    error NothingQueued();
    error DelayNotElapsed(uint256 applyAt, uint256 currentTimestamp);
    error RenounceDisabled();

    event PairCreated(address indexed token0, address indexed token1, address pair, uint256 index);
    event FeeToQueued(address indexed newFeeTo, uint256 applyAt);
    event FeeToSet(address indexed newFeeTo, uint256 applyAt);
    event FeeToCanceled(address indexed canceledFeeTo, uint256 applyAt);

    /// @notice Set the nonzero initial owner and fee recipient without an initial delay.
    constructor(address initialOwner, address initialFeeTo) Ownable(initialOwner) {
        if (initialFeeTo == address(0)) revert ZeroAddress();
        feeTo = initialFeeTo;
        emit FeeToSet(initialFeeTo, block.timestamp);
    }

    /// @notice Number of pairs created by this factory.
    function allPairsLength() external view returns (uint256) {
        return allPairs.length;
    }

    /// @notice Initialization-code hash used for deterministic pair address calculation.
    function pairCodeHash() external pure returns (bytes32) {
        return keccak256(type(NairaSwapPair).creationCode);
    }

    /// @notice Create a pair for distinct nonzero tokens, sorted by address; rejects duplicates.
    function createPair(address tokenA, address tokenB) external returns (address pair) {
        if (tokenA == tokenB) revert IdenticalAddresses();
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (token0 == address(0)) revert ZeroAddress();
        if (getPair[token0][token1] != address(0)) revert PairExists();
        bytes32 salt = keccak256(abi.encodePacked(token0, token1));
        NairaSwapPair deployed = new NairaSwapPair{salt: salt}();
        pair = address(deployed);
        // Initialization has no external token calls, so registration cannot be reentered.
        deployed.initialize(token0, token1);
        getPair[token0][token1] = pair;
        getPair[token1][token0] = pair;
        allPairs.push(pair);
        emit PairCreated(token0, token1, pair, allPairs.length);
    }

    /// @notice Queue a nonzero fee recipient; replacing a queue restarts the full delay.
    function queueFeeTo(address newFeeTo) external onlyOwner {
        if (newFeeTo == address(0)) revert ZeroAddress();
        pendingFeeTo = newFeeTo;
        pendingFeeToAt = block.timestamp + FEE_DELAY;
        emit FeeToQueued(newFeeTo, pendingFeeToAt);
    }

    /// @notice Anyone may apply the queued fee recipient once the full delay has elapsed.
    function applyFeeTo() external {
        uint256 applyAt = pendingFeeToAt;
        if (applyAt == 0) revert NothingQueued();
        if (block.timestamp < applyAt) revert DelayNotElapsed(applyAt, block.timestamp);
        address recipient = pendingFeeTo;
        delete pendingFeeTo;
        delete pendingFeeToAt;
        feeTo = recipient;
        emit FeeToSet(recipient, applyAt);
    }

    /// @notice Cancel a pending fee-recipient change; owner only.
    function cancelFeeTo() external onlyOwner {
        uint256 applyAt = pendingFeeToAt;
        if (applyAt == 0) revert NothingQueued();
        address recipient = pendingFeeTo;
        delete pendingFeeTo;
        delete pendingFeeToAt;
        emit FeeToCanceled(recipient, applyAt);
    }

    /// @notice Propose a nonzero new owner using two-step acceptance.
    function transferOwnership(address newOwner) public override onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        super.transferOwnership(newOwner);
    }

    /// @notice Always reverts; factory ownership may never be renounced.
    function renounceOwnership() public override onlyOwner {
        revert RenounceDisabled();
    }
}

contracts/NairaSwapPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {INairaSwapFactory} from "./interfaces/INairaSwapFactory.sol";

/// @notice Immutable V2-style constant-product pool with an ERC-2612 LP token.
/// @dev Inputs are measured from balances. No flash callback; swaps require prepaid input.
/// Rebasing tokens are unsupported. Direct donations may be skimmed permissionlessly.
contract NairaSwapPair is ERC20, ERC20Permit {
    using SafeERC20 for IERC20;

    /// @notice LP units permanently locked at the burn address on first mint.
    uint256 public constant MINIMUM_LIQUIDITY = 1000;
    /// @notice Factory authorized to initialize this pair.
    address public immutable factory;
    /// @notice Lower-address underlying token.
    address public token0;
    /// @notice Higher-address underlying token.
    address public token1;

    uint112 private reserve0;
    uint112 private reserve1;
    uint32 private blockTimestampLast;
    uint256 private unlocked = 1;

    /// @notice Cumulative UQ112x112 token1/token0 price, modulo 2**256.
    uint256 public price0CumulativeLast;
    /// @notice Cumulative UQ112x112 token0/token1 price, modulo 2**256.
    uint256 public price1CumulativeLast;
    /// @notice Reserve product after the last fee-enabled mint or burn.
    uint256 public kLast;

    struct SwapState {
        uint112 old0;
        uint112 old1;
        uint256 balance0;
        uint256 balance1;
        uint256 amount0In;
        uint256 amount1In;
    }

    error Forbidden();
    error AlreadyInitialized();
    error InvalidTokens();
    error InvalidTo();
    error Locked();
    error ReserveOverflow(uint256 balance0, uint256 balance1);
    error InsufficientLiquidity(uint256 actual, uint256 bound);
    error InsufficientInputAmount(uint256 amount0In, uint256 amount1In);
    error InsufficientOutputAmount(uint256 amount0Out, uint256 amount1Out);
    error InvariantViolation();
    error NonEmptyData();

    event Initialized(address indexed token0, address indexed token1);
    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(address indexed sender, uint256 amount0In, uint256 amount1In, uint256 amount0Out, uint256 amount1Out, address indexed to);
    event Sync(uint112 reserve0, uint112 reserve1);
    event Skim(address indexed to, uint256 amount0, uint256 amount1);

    modifier lock() {
        if (unlocked != 1) revert Locked();
        unlocked = 0;
        _;
        unlocked = 1;
    }

    /// @notice Deploy an uninitialized pair owned by its deploying factory.
    constructor() ERC20("NairaSwap LP", "NSWAP-LP") ERC20Permit("NairaSwap LP") {
        factory = msg.sender;
    }

    /// @notice Initialize sorted tokens exactly once; only the deploying factory may call.
    function initialize(address token0_, address token1_) external {
        if (msg.sender != factory) revert Forbidden();
        if (token0 != address(0)) revert AlreadyInitialized();
        if (token0_ == address(0) || token0_ >= token1_) revert InvalidTokens();
        token0 = token0_;
        token1 = token1_;
        emit Initialized(token0_, token1_);
    }

    /// @notice Return stored reserves and the last modulo-2**32 update timestamp.
    function getReserves() external view returns (uint112, uint112, uint32) {
        return (reserve0, reserve1, blockTimestampLast);
    }

    /// @notice Mint LP to `to` for actual underlying balances deposited since the last update.
    function mint(address to) external lock returns (uint256 liquidity) {
        _validateTo(to);
        uint112 old0 = reserve0;
        uint112 old1 = reserve1;
        (uint256 balance0, uint256 balance1) = _balances();
        _checkBalances(balance0, balance1);
        uint256 amount0 = balance0 - old0;
        uint256 amount1 = balance1 - old1;
        bool feeOn = _mintFee(old0, old1);
        uint256 supply = totalSupply();
        if (supply == 0) {
            uint256 root = Math.sqrt(amount0 * amount1);
            if (root <= MINIMUM_LIQUIDITY) revert InsufficientLiquidity(root, MINIMUM_LIQUIDITY);
            liquidity = root - MINIMUM_LIQUIDITY;
            _mint(address(0xdead), MINIMUM_LIQUIDITY);
        } else {
            if (old0 == 0 || old1 == 0) revert InsufficientLiquidity(Math.min(old0, old1), 1);
            liquidity = Math.min(amount0 * supply / old0, amount1 * supply / old1);
        }
        if (liquidity == 0) revert InsufficientLiquidity(liquidity, 1);
        _mint(to, liquidity);
        _update(balance0, balance1, old0, old1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;
        emit Mint(msg.sender, amount0, amount1);
    }

    /// @notice Burn all LP held by the pair and transfer its pro-rata underlying balances to `to`.
    function burn(address to) external lock returns (uint256 amount0, uint256 amount1) {
        _validateTo(to);
        uint112 old0 = reserve0;
        uint112 old1 = reserve1;
        (uint256 balance0, uint256 balance1) = _balances();
        uint256 liquidity = balanceOf(address(this));
        bool feeOn = _mintFee(old0, old1);
        uint256 supply = totalSupply();
        if (supply == 0) revert InsufficientLiquidity(supply, 1);
        amount0 = liquidity * balance0 / supply;
        amount1 = liquidity * balance1 / supply;
        if (amount0 == 0 || amount1 == 0) revert InsufficientLiquidity(Math.min(amount0, amount1), 1);
        _burn(address(this), liquidity);
        IERC20(token0).safeTransfer(to, amount0);
        IERC20(token1).safeTransfer(to, amount1);
        (balance0, balance1) = _balances();
        _update(balance0, balance1, old0, old1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;
        emit Burn(msg.sender, amount0, amount1, to);
    }

    /// @notice Exchange prepaid input for outputs, enforcing a 0.30% fee-adjusted invariant.
    /// @param data Must be empty; flash-swap callbacks are intentionally unsupported.
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external lock {
        if (data.length != 0) revert NonEmptyData();
        if (amount0Out == 0 && amount1Out == 0) revert InsufficientOutputAmount(amount0Out, amount1Out);
        _validateTo(to);
        SwapState memory state;
        state.old0 = reserve0;
        state.old1 = reserve1;
        if (amount0Out >= state.old0) revert InsufficientLiquidity(state.old0, amount0Out);
        if (amount1Out >= state.old1) revert InsufficientLiquidity(state.old1, amount1Out);
        if (amount0Out != 0) IERC20(token0).safeTransfer(to, amount0Out);
        if (amount1Out != 0) IERC20(token1).safeTransfer(to, amount1Out);
        (state.balance0, state.balance1) = _balances();
        _checkBalances(state.balance0, state.balance1);
        state.amount0In = state.balance0 > uint256(state.old0) - amount0Out
            ? state.balance0 - (uint256(state.old0) - amount0Out) : 0;
        state.amount1In = state.balance1 > uint256(state.old1) - amount1Out
            ? state.balance1 - (uint256(state.old1) - amount1Out) : 0;
        if (state.amount0In == 0 && state.amount1In == 0) revert InsufficientInputAmount(state.amount0In, state.amount1In);
        uint256 adjusted0 = state.balance0 * 1000 - state.amount0In * 3;
        uint256 adjusted1 = state.balance1 * 1000 - state.amount1In * 3;
        if (adjusted0 * adjusted1 < uint256(state.old0) * state.old1 * 1_000_000) {
            revert InvariantViolation();
        }
        // Token interactions precede reserve effects intentionally: actual post-transfer balances
        // must enforce the invariant. The shared lock protects every reserve-changing entry point.
        _update(state.balance0, state.balance1, state.old0, state.old1);
        emit Swap(msg.sender, state.amount0In, state.amount1In, amount0Out, amount1Out, to);
    }

    /// @notice Send only balances in excess of reserves to `to`.
    function skim(address to) external lock {
        _validateTo(to);
        (uint256 balance0, uint256 balance1) = _balances();
        uint256 amount0 = balance0 - reserve0;
        uint256 amount1 = balance1 - reserve1;
        if (amount0 != 0) IERC20(token0).safeTransfer(to, amount0);
        if (amount1 != 0) IERC20(token1).safeTransfer(to, amount1);
        emit Skim(to, amount0, amount1);
    }

    /// @notice Synchronize reserves to actual balances without moving tokens.
    function sync() external lock {
        (uint256 balance0, uint256 balance1) = _balances();
        _update(balance0, balance1, reserve0, reserve1);
    }

    function _validateTo(address to) private view {
        if (to == address(0) || to == address(this) || to == token0 || to == token1) revert InvalidTo();
    }

    function _balances() private view returns (uint256, uint256) {
        return (IERC20(token0).balanceOf(address(this)), IERC20(token1).balanceOf(address(this)));
    }

    function _checkBalances(uint256 balance0, uint256 balance1) private pure {
        if (balance0 > type(uint112).max || balance1 > type(uint112).max) revert ReserveOverflow(balance0, balance1);
    }

    function _update(uint256 balance0, uint256 balance1, uint112 old0, uint112 old1) private {
        _checkBalances(balance0, balance1);
        uint32 timestamp = uint32(block.timestamp);
        // The sole unchecked block: V2 timestamps wrap modulo 2**32 and cumulative
        // UQ112x112 prices wrap modulo 2**256. Integrators take modular differences.
        unchecked {
            uint32 elapsed = timestamp - blockTimestampLast;
            if (elapsed != 0 && old0 != 0 && old1 != 0) {
                price0CumulativeLast += ((uint256(old1) << 112) / old0) * elapsed;
                price1CumulativeLast += ((uint256(old0) << 112) / old1) * elapsed;
            }
        }
        reserve0 = uint112(balance0);
        reserve1 = uint112(balance1);
        blockTimestampLast = timestamp;
        emit Sync(reserve0, reserve1);
    }

    function _mintFee(uint112 old0, uint112 old1) private returns (bool feeOn) {
        address recipient = INairaSwapFactory(factory).feeTo();
        feeOn = recipient != address(0);
        uint256 previousK = kLast;
        if (feeOn) {
            if (previousK != 0) {
                uint256 rootK = Math.sqrt(uint256(old0) * old1);
                uint256 rootKLast = Math.sqrt(previousK);
                if (rootK > rootKLast) {
                    uint256 liquidity = totalSupply() * (rootK - rootKLast) / (rootK * 5 + rootKLast);
                    if (liquidity != 0) _mint(recipient, liquidity);
                }
            }
        } else if (previousK != 0) {
            kLast = 0;
        }
    }
}

contracts/NairaSwapRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {INairaSwapFactory} from "./interfaces/INairaSwapFactory.sol";
import {INairaSwapPair} from "./interfaces/INairaSwapPair.sol";
import {NairaSwapLibrary} from "./libraries/NairaSwapLibrary.sol";

/// @notice Token-only routing; swaps/adds can pause, liquidity removal cannot.
/// @dev Tokens move directly between users and pairs. The router grants no token approvals.
/// Administrative functions retain their specified deadline-free signatures; all user fund
/// operations require deadlines and slippage bounds. ERC-2612 permits are exact-amount only.
contract NairaSwapRouter is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Factory used for every routed pair.
    address public immutable factory;
    /// @notice Emergency pause-only operator; initially the owner.
    address public pauser;
    /// @notice Maximum number of hops; paths contain at most five token addresses.
    uint256 public constant MAX_PATH = 4;

    struct AddRequest {
        address tokenA;
        address tokenB;
        uint256 desiredA;
        uint256 desiredB;
        uint256 minA;
        uint256 minB;
        address to;
    }

    struct RemoveRequest {
        address tokenA;
        address tokenB;
        uint256 liquidity;
        uint256 minA;
        uint256 minB;
        address to;
    }

    error ZeroAddress();
    error InvalidTo();
    error Forbidden();
    error InvalidFactory(address factory);
    error Expired(uint256 deadline, uint256 currentTimestamp);
    error InsufficientInputAmount(uint256 actual, uint256 minimum);
    error InsufficientOutputAmount(uint256 actual, uint256 minimum);
    error ExcessiveInputAmount(uint256 actual, uint256 maximum);
    error RenounceDisabled();

    event PauserSet(address indexed account);
    event TokensRescued(address indexed token, address indexed to, uint256 amount);

    modifier ensure(uint256 deadline) {
        if (block.timestamp > deadline) revert Expired(deadline, block.timestamp);
        _;
    }

    /// @notice Configure the factory and nonzero owner; the owner is also the initial pauser.
    constructor(address factory_, address initialOwner) Ownable(initialOwner) {
        if (factory_ == address(0)) revert ZeroAddress();
        if (factory_.code.length == 0) revert InvalidFactory(factory_);
        (bool success, bytes memory result) = factory_.staticcall(
            abi.encodeWithSelector(INairaSwapFactory.pairCodeHash.selector)
        );
        if (!success || result.length != 32) revert InvalidFactory(factory_);
        factory = factory_;
        pauser = initialOwner;
        emit PauserSet(initialOwner);
    }

    /// @notice Add optimal liquidity, checking actual received amounts against both minima.
    /// @dev Desired amounts cap transfers; outputs are actual amounts deposited and LP minted.
    function addLiquidity(
        address tokenA, address tokenB, uint256 amountADesired, uint256 amountBDesired,
        uint256 amountAMin, uint256 amountBMin, address to, uint256 deadline
    ) external ensure(deadline) whenNotPaused nonReentrant returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        AddRequest memory request;
        request.tokenA = tokenA;
        request.tokenB = tokenB;
        request.desiredA = amountADesired;
        request.desiredB = amountBDesired;
        request.minA = amountAMin;
        request.minB = amountBMin;
        request.to = to;
        return _add(request);
    }

    /// @notice Remove LP and enforce actual recipient token minima; never blocked by pause.
    function removeLiquidity(
        address tokenA, address tokenB, uint256 liquidity, uint256 amountAMin,
        uint256 amountBMin, address to, uint256 deadline
    ) external ensure(deadline) nonReentrant returns (uint256 amountA, uint256 amountB) {
        RemoveRequest memory request;
        request.tokenA = tokenA;
        request.tokenB = tokenB;
        request.liquidity = liquidity;
        request.minA = amountAMin;
        request.minB = amountBMin;
        request.to = to;
        return _remove(request);
    }

    /// @notice Remove liquidity using a permit for exactly `liquidity`; never blocked by pause.
    /// @dev No approveMax flag: persistent unlimited approvals are intentionally unsupported.
    function removeLiquidityWithPermit(
        address tokenA, address tokenB, uint256 liquidity, uint256 amountAMin,
        uint256 amountBMin, address to, uint256 deadline, uint8 v, bytes32 r, bytes32 s
    ) external ensure(deadline) nonReentrant returns (uint256 amountA, uint256 amountB) {
        RemoveRequest memory request;
        request.tokenA = tokenA;
        request.tokenB = tokenB;
        request.liquidity = liquidity;
        request.minA = amountAMin;
        request.minB = amountBMin;
        request.to = to;
        return _permitAndRemove(request, deadline, v, r, s);
    }

    /// @notice Swap exact input for at least the specified output before deadline.
    /// @dev Use the dedicated supporting function for fee-on-transfer input/intermediate tokens.
    function swapExactTokensForTokens(
        uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external ensure(deadline) whenNotPaused nonReentrant returns (uint256[] memory amounts) {
        _validateTo(to);
        amounts = NairaSwapLibrary.getAmountsOut(factory, amountIn, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert InsufficientOutputAmount(amounts[amounts.length - 1], amountOutMin);
        uint256 beforeBalance = IERC20(path[path.length - 1]).balanceOf(to);
        IERC20(path[0]).safeTransferFrom(msg.sender, _pair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
        uint256 received = IERC20(path[path.length - 1]).balanceOf(to) - beforeBalance;
        if (received < amountOutMin) {
            revert InsufficientOutputAmount(received, amountOutMin);
        }
    }

    /// @notice Obtain the requested output spending no more than `amountInMax` before deadline.
    function swapTokensForExactTokens(
        uint256 amountOut, uint256 amountInMax, address[] calldata path, address to, uint256 deadline
    ) external ensure(deadline) whenNotPaused nonReentrant returns (uint256[] memory amounts) {
        _validateTo(to);
        amounts = NairaSwapLibrary.getAmountsIn(factory, amountOut, path);
        if (amounts[0] > amountInMax) revert ExcessiveInputAmount(amounts[0], amountInMax);
        uint256 beforeBalance = IERC20(path[path.length - 1]).balanceOf(to);
        IERC20(path[0]).safeTransferFrom(msg.sender, _pair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
        uint256 received = IERC20(path[path.length - 1]).balanceOf(to) - beforeBalance;
        if (received < amountOut) {
            revert InsufficientOutputAmount(received, amountOut);
        }
    }

    /// @notice Swap exact input using actual pair input balances and actual recipient minimum output.
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external ensure(deadline) whenNotPaused nonReentrant {
        _validateTo(to);
        NairaSwapLibrary.validatePath(path);
        if (amountIn == 0) revert InsufficientInputAmount(amountIn, 1);
        uint256 beforeBalance = IERC20(path[path.length - 1]).balanceOf(to);
        IERC20(path[0]).safeTransferFrom(msg.sender, _pair(path[0], path[1]), amountIn);
        for (uint256 i; i + 1 < path.length; i++) {
            address recipient = i + 2 < path.length ? _pair(path[i + 1], path[i + 2]) : to;
            _supportingHop(path[i], path[i + 1], recipient);
        }
        uint256 received = IERC20(path[path.length - 1]).balanceOf(to) - beforeBalance;
        if (received < amountOutMin) {
            revert InsufficientOutputAmount(received, amountOutMin);
        }
    }

    /// @notice Quote a proportional amount from reserves without a swap fee.
    function quote(uint256 amountA, uint256 reserveA, uint256 reserveB) external pure returns (uint256) {
        return NairaSwapLibrary.quote(amountA, reserveA, reserveB);
    }

    /// @notice Quote output after the 0.30% swap fee.
    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) external pure returns (uint256) {
        return NairaSwapLibrary.getAmountOut(amountIn, reserveIn, reserveOut);
    }

    /// @notice Quote required input rounded up, including the swap fee.
    function getAmountIn(uint256 amountOut, uint256 reserveIn, uint256 reserveOut) external pure returns (uint256) {
        return NairaSwapLibrary.getAmountIn(amountOut, reserveIn, reserveOut);
    }

    /// @notice Quote each hop's amounts for exact input, for at most four hops.
    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory) {
        return NairaSwapLibrary.getAmountsOut(factory, amountIn, path);
    }

    /// @notice Quote each hop's amounts for exact output, for at most four hops.
    function getAmountsIn(uint256 amountOut, address[] calldata path) external view returns (uint256[] memory) {
        return NairaSwapLibrary.getAmountsIn(factory, amountOut, path);
    }

    /// @notice Set a nonzero pause-only operator; owner only.
    function setPauser(address newPauser) external onlyOwner nonReentrant {
        if (newPauser == address(0)) revert ZeroAddress();
        pauser = newPauser;
        emit PauserSet(newPauser);
    }

    /// @notice Pause swaps and adds; callable by owner or pauser, without blocking exits.
    function pause() external nonReentrant {
        if (msg.sender != owner() && msg.sender != pauser) revert Forbidden();
        _pause();
    }

    /// @notice Resume swaps and adds; only the owner may unpause.
    function unpause() external onlyOwner nonReentrant {
        _unpause();
    }

    /// @notice Rescue stray tokens; no pool reserves or user allowances can be accessed.
    function rescueTokens(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        _validateTo(to);
        IERC20(token).safeTransfer(to, amount);
        emit TokensRescued(token, to, amount);
    }

    /// @notice Propose a nonzero new owner for two-step acceptance.
    function transferOwnership(address newOwner) public override onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        super.transferOwnership(newOwner);
    }

    /// @notice Always reverts; router ownership cannot be renounced.
    function renounceOwnership() public override onlyOwner {
        revert RenounceDisabled();
    }

    function _add(AddRequest memory request) private returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        _validateTo(request.to);
        address pair = INairaSwapFactory(factory).getPair(request.tokenA, request.tokenB);
        if (pair == address(0)) pair = INairaSwapFactory(factory).createPair(request.tokenA, request.tokenB);
        (amountA, amountB) = _optimal(request);
        uint256 beforeA = IERC20(request.tokenA).balanceOf(pair);
        uint256 beforeB = IERC20(request.tokenB).balanceOf(pair);
        IERC20(request.tokenA).safeTransferFrom(msg.sender, pair, amountA);
        IERC20(request.tokenB).safeTransferFrom(msg.sender, pair, amountB);
        amountA = IERC20(request.tokenA).balanceOf(pair) - beforeA;
        amountB = IERC20(request.tokenB).balanceOf(pair) - beforeB;
        if (amountA < request.minA) revert InsufficientInputAmount(amountA, request.minA);
        if (amountB < request.minB) revert InsufficientInputAmount(amountB, request.minB);
        liquidity = INairaSwapPair(pair).mint(request.to);
    }

    function _optimal(AddRequest memory request) private view returns (uint256 amountA, uint256 amountB) {
        if (INairaSwapPair(_pair(request.tokenA, request.tokenB)).totalSupply() == 0) {
            (amountA, amountB) = (request.desiredA, request.desiredB);
        } else {
            (uint256 reserveA, uint256 reserveB) = NairaSwapLibrary.getReserves(factory, request.tokenA, request.tokenB);
            uint256 optimalB = NairaSwapLibrary.quote(request.desiredA, reserveA, reserveB);
            if (optimalB <= request.desiredB) {
                (amountA, amountB) = (request.desiredA, optimalB);
            } else {
                uint256 optimalA = NairaSwapLibrary.quote(request.desiredB, reserveB, reserveA);
                if (optimalA > request.desiredA) revert ExcessiveInputAmount(optimalA, request.desiredA);
                (amountA, amountB) = (optimalA, request.desiredB);
            }
        }
        if (amountA < request.minA) revert InsufficientInputAmount(amountA, request.minA);
        if (amountB < request.minB) revert InsufficientInputAmount(amountB, request.minB);
    }

    function _permitAndRemove(RemoveRequest memory request, uint256 deadline, uint8 v, bytes32 r, bytes32 s)
        private returns (uint256, uint256)
    {
        address pair = _pair(request.tokenA, request.tokenB);
        // A third party may have already submitted the same permit; the allowance must
        // still cover the exact removal if so. Invalid signatures never grant authority.
        try INairaSwapPair(pair).permit(msg.sender, address(this), request.liquidity, deadline, v, r, s) {} catch {
            if (IERC20(pair).allowance(msg.sender, address(this)) < request.liquidity) revert Forbidden();
        }
        return _remove(request);
    }

    function _remove(RemoveRequest memory request) private returns (uint256 amountA, uint256 amountB) {
        _validateTo(request.to);
        address pair = _pair(request.tokenA, request.tokenB);
        uint256 beforeA = IERC20(request.tokenA).balanceOf(request.to);
        uint256 beforeB = IERC20(request.tokenB).balanceOf(request.to);
        IERC20(pair).safeTransferFrom(msg.sender, pair, request.liquidity);
        INairaSwapPair(pair).burn(request.to);
        amountA = IERC20(request.tokenA).balanceOf(request.to) - beforeA;
        amountB = IERC20(request.tokenB).balanceOf(request.to) - beforeB;
        if (amountA < request.minA) revert InsufficientOutputAmount(amountA, request.minA);
        if (amountB < request.minB) revert InsufficientOutputAmount(amountB, request.minB);
    }

    function _swap(uint256[] memory amounts, address[] calldata path, address to) private {
        for (uint256 i; i + 1 < path.length; i++) {
            address recipient = i + 2 < path.length ? _pair(path[i + 1], path[i + 2]) : to;
            _swapHop(path[i], path[i + 1], amounts[i + 1], recipient);
        }
    }

    function _supportingHop(address input, address output, address recipient) private {
        (uint256 reserveIn, uint256 reserveOut) = NairaSwapLibrary.getReserves(factory, input, output);
        uint256 received = IERC20(input).balanceOf(_pair(input, output)) - reserveIn;
        _swapHop(input, output, NairaSwapLibrary.getAmountOut(received, reserveIn, reserveOut), recipient);
    }

    function _swapHop(address input, address output, uint256 amountOut, address recipient) private {
        (address token0,) = NairaSwapLibrary.sortTokens(input, output);
        (uint256 amount0Out, uint256 amount1Out) = input == token0
            ? (uint256(0), amountOut) : (amountOut, uint256(0));
        INairaSwapPair(_pair(input, output)).swap(amount0Out, amount1Out, recipient, "");
    }

    function _pair(address tokenA, address tokenB) private view returns (address) {
        return NairaSwapLibrary.pairFor(factory, tokenA, tokenB);
    }

    function _validateTo(address to) private view {
        if (to == address(0) || to == address(this)) revert InvalidTo();
    }
}

contracts/NairaSwapTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {INairaSwapPair} from "./interfaces/INairaSwapPair.sol";

/// @notice Holds protocol LP fees and redeemed underlying tokens; withdrawals go only to payout.
contract NairaSwapTreasury is Ownable2Step, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Minimum payout-change delay.
    uint256 public constant PAYOUT_DELAY = 2 days;
    /// @notice Exclusive destination of treasury withdrawals.
    address public payout;
    /// @notice Queued payout, or zero if nothing is queued.
    address public pendingPayout;
    /// @notice Earliest application timestamp, or zero if nothing is queued.
    uint256 public pendingPayoutAt;

    error ZeroAddress();
    error NothingQueued();
    error DelayNotElapsed(uint256 applyAt, uint256 currentTimestamp);
    error RenounceDisabled();
    error InsufficientLiquidity();

    event PayoutQueued(address indexed newPayout, uint256 applyAt);
    event PayoutSet(address indexed newPayout, uint256 applyAt);
    event PayoutCanceled(address indexed canceledPayout, uint256 applyAt);
    event Redeemed(address indexed pair, uint256 liquidity, address indexed to);
    event Withdrawn(address indexed token, uint256 amount, address indexed to);

    /// @notice Set the nonzero initial owner and initial payout destination.
    constructor(address initialOwner, address initialPayout) Ownable(initialOwner) {
        if (initialPayout == address(0)) revert ZeroAddress();
        payout = initialPayout;
        emit PayoutSet(initialPayout, block.timestamp);
    }

    /// @notice Queue a nonzero payout destination; replacing a queue restarts the delay.
    function queuePayout(address newPayout) external onlyOwner nonReentrant {
        if (newPayout == address(0)) revert ZeroAddress();
        pendingPayout = newPayout;
        pendingPayoutAt = block.timestamp + PAYOUT_DELAY;
        emit PayoutQueued(newPayout, pendingPayoutAt);
    }

    /// @notice Anyone may apply the queued payout once its two-day delay has elapsed.
    function applyPayout() external nonReentrant {
        uint256 applyAt = pendingPayoutAt;
        if (applyAt == 0) revert NothingQueued();
        if (block.timestamp < applyAt) revert DelayNotElapsed(applyAt, block.timestamp);
        address recipient = pendingPayout;
        delete pendingPayout;
        delete pendingPayoutAt;
        payout = recipient;
        emit PayoutSet(recipient, applyAt);
    }

    /// @notice Cancel the queued payout change; owner only.
    function cancelPayout() external onlyOwner nonReentrant {
        uint256 applyAt = pendingPayoutAt;
        if (applyAt == 0) revert NothingQueued();
        address recipient = pendingPayout;
        delete pendingPayout;
        delete pendingPayoutAt;
        emit PayoutCanceled(recipient, applyAt);
    }

    /// @notice Redeem treasury-owned LP tokens with all underlying proceeds sent here.
    function redeem(address pair, uint256 liquidity) external onlyOwner nonReentrant {
        if (pair == address(0)) revert ZeroAddress();
        if (liquidity == 0) revert InsufficientLiquidity();
        IERC20(pair).safeTransfer(pair, liquidity);
        INairaSwapPair(pair).burn(address(this));
        emit Redeemed(pair, liquidity, address(this));
    }

    /// @notice Withdraw tokens only to the configured payout address; owner only.
    function withdraw(address token, uint256 amount) external onlyOwner nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        address recipient = payout;
        IERC20(token).safeTransfer(recipient, amount);
        emit Withdrawn(token, amount, recipient);
    }

    /// @notice Propose a nonzero new owner using two-step acceptance.
    function transferOwnership(address newOwner) public override onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        super.transferOwnership(newOwner);
    }

    /// @notice Always reverts; treasury ownership may never be renounced.
    function renounceOwnership() public override onlyOwner {
        revert RenounceDisabled();
    }
}

contracts/interfaces/INairaSwapFactory.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice Deterministic pool registry and delayed protocol-fee administration.
interface INairaSwapFactory {
    event PairCreated(address indexed token0, address indexed token1, address pair, uint256 index);
    event FeeToQueued(address indexed newFeeTo, uint256 applyAt);
    event FeeToSet(address indexed newFeeTo, uint256 applyAt);
    event FeeToCanceled(address indexed canceledFeeTo, uint256 applyAt);

    /// @notice Current protocol-fee recipient.
    function feeTo() external view returns (address);
    /// @notice Queued protocol-fee recipient.
    function pendingFeeTo() external view returns (address);
    /// @notice Earliest application time, or zero when nothing is queued.
    function pendingFeeToAt() external view returns (uint256);
    /// @notice Fee-recipient timelock duration.
    function FEE_DELAY() external view returns (uint256);
    /// @notice Pair for either ordering of two tokens, or zero.
    function getPair(address tokenA, address tokenB) external view returns (address);
    /// @notice Pair at a zero-based registry index.
    function allPairs(uint256 index) external view returns (address);
    /// @notice Number of pairs created.
    function allPairsLength() external view returns (uint256);
    /// @notice CREATE2 initialization-code hash used by this factory.
    function pairCodeHash() external view returns (bytes32);
    /// @notice Permissionlessly deploy and register a new sorted pair.
    function createPair(address tokenA, address tokenB) external returns (address pair);
    /// @notice Queue a nonzero fee recipient; owner only, resets the full delay.
    function queueFeeTo(address newFeeTo) external;
    /// @notice Permissionlessly apply a queued fee recipient after the delay.
    function applyFeeTo() external;
    /// @notice Cancel the queued fee recipient; owner only.
    function cancelFeeTo() external;
    /// @notice Current two-step owner.
    function owner() external view returns (address);
    /// @notice Proposed two-step owner.
    function pendingOwner() external view returns (address);
    /// @notice Propose a nonzero new owner; current owner only.
    function transferOwnership(address newOwner) external;
    /// @notice Accept ownership as the pending owner.
    function acceptOwnership() external;
    /// @notice Always reverts: ownership cannot be renounced.
    function renounceOwnership() external;
}

contracts/interfaces/INairaSwapPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

/// @notice Constant-product pool and ERC-2612 liquidity token.
interface INairaSwapPair is IERC20Metadata, IERC20Permit {
    event Initialized(address indexed token0, address indexed token1);
    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(address indexed sender, uint256 amount0In, uint256 amount1In, uint256 amount0Out, uint256 amount1Out, address indexed to);
    event Sync(uint112 reserve0, uint112 reserve1);
    event Skim(address indexed to, uint256 amount0, uint256 amount1);

    /// @notice Permanently locked minimum LP supply.
    function MINIMUM_LIQUIDITY() external view returns (uint256);
    /// @notice Factory that deployed this pair.
    function factory() external view returns (address);
    /// @notice Lower-address underlying token.
    function token0() external view returns (address);
    /// @notice Higher-address underlying token.
    function token1() external view returns (address);
    /// @notice Stored balances and the last update's modulo-2**32 timestamp.
    function getReserves() external view returns (uint112, uint112, uint32);
    /// @notice Cumulative UQ112x112 token1/token0 price, modulo 2**256.
    function price0CumulativeLast() external view returns (uint256);
    /// @notice Cumulative UQ112x112 token0/token1 price, modulo 2**256.
    function price1CumulativeLast() external view returns (uint256);
    /// @notice Reserve product at the last fee-enabled liquidity event.
    function kLast() external view returns (uint256);
    /// @notice Initialize sorted nonzero tokens; factory only, once.
    function initialize(address token0_, address token1_) external;
    /// @notice Mint LP against underlying tokens already transferred to the pair.
    function mint(address to) external returns (uint256 liquidity);
    /// @notice Burn LP already transferred to the pair and deliver underlying tokens.
    function burn(address to) external returns (uint256 amount0, uint256 amount1);
    /// @notice Swap prepaid input for outputs; data must be empty (no callback).
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external;
    /// @notice Transfer balances above reserves to the recipient.
    function skim(address to) external;
    /// @notice Update stored reserves to actual token balances.
    function sync() external;
}

